package com.jnapanam.sportszone.admin.service;
import com.jnapanam.sportszone.admin.dto.*;import com.jnapanam.sportszone.admin.repository.AuditLogRepository;import java.time.LocalDate;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AdminReportingService{private final JdbcTemplate jdbc;private final AuditLogRepository audit;public AdminReportingService(JdbcTemplate j,AuditLogRepository a){jdbc=j;audit=a;}
 @Transactional(readOnly=true)public DashboardResponse dashboard(LocalDate from,LocalDate to){LocalDate[]r=range(from,to);long gross=value("SELECT COALESCE(SUM(amount_paise),0) FROM payment_orders WHERE status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED') AND created_at::date BETWEEN ? AND ?",r);long refunds=value("SELECT COALESCE(SUM(pr.amount_paise),0) FROM payment_refunds pr JOIN payment_orders po ON po.id=pr.payment_order_id WHERE pr.status='PROCESSED' AND pr.processed_at::date BETWEEN ? AND ?",r);return new DashboardResponse(r[0],r[1],value("SELECT COUNT(*) FROM users"),value("SELECT COUNT(*) FROM sports WHERE status='ACTIVE'"),value("SELECT COUNT(*) FROM facilities WHERE status='ACTIVE'"),value("SELECT COUNT(*) FROM bookings WHERE confirmed_at::date BETWEEN ? AND ?",r),value("SELECT COUNT(*) FROM bookings WHERE checked_in_at::date BETWEEN ? AND ?",r),value("SELECT COUNT(*) FROM customer_memberships WHERE status='ACTIVE'"),value("SELECT COUNT(*) FROM training_enrollments WHERE status='ENROLLED'"),value("SELECT COUNT(*) FROM tournaments WHERE status IN ('REGISTRATION_OPEN','REGISTRATION_CLOSED','IN_PROGRESS')"),gross,refunds,gross-refunds);}
 @Transactional(readOnly=true)public ReconciliationResponse reconciliation(){return new ReconciliationResponse(value("SELECT COUNT(*) FROM payment_orders WHERE status='CREATED'"),value("SELECT COUNT(*) FROM payment_orders WHERE status='PAID'"),value("SELECT COUNT(*) FROM payment_orders WHERE status='PARTIALLY_REFUNDED'"),value("SELECT COUNT(*) FROM payment_orders WHERE status='REFUNDED'"),value("SELECT COUNT(*) FROM payment_refunds WHERE status='PROCESSED'"),value("SELECT COUNT(*) FROM payment_orders WHERE status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED') AND provider_payment_id IS NULL"));}
 @Transactional(readOnly=true)public List<Map<String,Object>>revenue(LocalDate from,LocalDate to){LocalDate[]r=range(from,to);return jdbc.queryForList("SELECT created_at::date AS date,currency,SUM(amount_paise) AS gross_paise,COUNT(*) AS payments FROM payment_orders WHERE status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED') AND created_at::date BETWEEN ? AND ? GROUP BY created_at::date,currency ORDER BY date",r[0],r[1]);}
 @Transactional(readOnly=true)public List<Map<String,Object>>bookings(LocalDate from,LocalDate to){LocalDate[]r=range(from,to);return jdbc.queryForList("SELECT f.name AS facility,s.name AS sport,COUNT(*) AS bookings,SUM(b.quantity) AS participants,COUNT(b.checked_in_at) AS checked_in FROM bookings b JOIN booking_slots bs ON bs.id=b.slot_id JOIN facilities f ON f.id=bs.facility_id JOIN sports s ON s.id=f.sport_id WHERE b.confirmed_at::date BETWEEN ? AND ? GROUP BY f.name,s.name ORDER BY bookings DESC",r[0],r[1]);}
 @Transactional(readOnly=true)public List<Map<String,Object>>memberships(){return jdbc.queryForList("SELECT mp.name AS plan,cm.status,COUNT(*) AS subscriptions FROM customer_memberships cm JOIN membership_plans mp ON mp.id=cm.plan_id GROUP BY mp.name,cm.status ORDER BY mp.name,cm.status");}
 @Transactional(readOnly=true)public List<AuditLogResponse>audit(int limit){int safe=Math.max(1,Math.min(limit,500));return audit.findAllByOrderByOccurredAtDesc(PageRequest.of(0,safe)).stream().map(AuditLogResponse::from).toList();}
 private long value(String sql,Object...args){Number n=jdbc.queryForObject(sql,Number.class,args);return n==null?0:n.longValue();}private static LocalDate[]range(LocalDate f,LocalDate t){LocalDate to=t==null?LocalDate.now():t;LocalDate from=f==null?to.withDayOfMonth(1):f;if(to.isBefore(from))throw new IllegalArgumentException("Invalid report date range");return new LocalDate[]{from,to};}}
